    /// <summary>返回该键的非空 path 数据；未知键返回 null（自检/回归测试用）。</summary>
    internal static string? TryGetPath(string key) =>
        Paths.TryGetValue(key, out string? value) && !string.IsNullOrEmpty(value) ? value : null;

    /// <summary>目录是否包含该键且 path 数据非空。</summary>
    internal static bool HasIcon(string key) => TryGetPath(key) is not null;

    /// <summary>按稳定键创建矢量图标；未知键回落默认图标，不抛错。</summary>
    internal static PathIcon CreateIcon(string key) => new()
    {
        Data = (Geometry)XamlBindingHelper.ConvertValue(
            typeof(Geometry), TryGetPath(key) ?? Paths[DefaultKey]),
    };
}
